import openpyxl, os
wb = openpyxl.load_workbook(os.environ['OUT_XLSX'])
prod = wb['Productivity']
mp = {}
for r in range(1, prod.max_row+1):
    a = prod.cell(r,1).value
    b = prod.cell(r,2).value
    if a is not None and b is not None and str(a).strip() and str(b).strip():
        mp[str(a).strip()] = b
op = wb['Open']
for r in range(1, op.max_row+1):
    for col in (3,11):
        c = op.cell(r,col)
        v = c.value
        if v is not None and str(v).strip() in mp:
            c.value = mp[str(v).strip()]
wb.save(os.environ['OUT_XLSX'])
print('done', len(mp))
